from decimal import Decimal


def _value(mapping: dict | None, key: str) -> object:
    if mapping is None:
        return ""
    value = mapping.get(key, "")
    return "" if value is None else value


def _number(value: object) -> Decimal:
    if value == "" or value is None:
        return Decimal("0")
    return Decimal(str(value))


def _lookup(
    tables: dict | None,
    table_name: str,
    key_col: str,
    key_val: object,
    out_col: str,
) -> object:
    if not tables:
        return ""

    for row in tables.get(table_name, []):
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get(key_col, "") == key_val:
            value = row.get(out_col, "")
            return "" if value is None else value
    return ""


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    errors: list[dict] = []

    if table == "ORD_HEADER":
        if event in ("INSERT", "UPDATE"):
            discount = _number(_value(record, "DISC_PCT"))
            if not (discount >= Decimal("0") and discount <= Decimal("100")):
                errors.append(
                    {
                        "code": "E5001",
                        "message": "Discount out of range",
                        "severity": "BLOCK",
                    }
                )

        if event == "UPDATE":
            discount = _number(_value(record, "DISC_PCT"))
            role = _lookup(
                tables,
                "USR_MASTER",
                "USR_ID",
                _value(record, "OWNER_UID"),
                "ROLE_ID",
            )
            if not (
                not (
                    discount > Decimal("20")
                    and role != "MGR"
                    and role != "ADMIN"
                )
            ):
                errors.append(
                    {
                        "code": "E5002",
                        "message": "Discount over 20 percent requires manager role",
                        "severity": "BLOCK",
                    }
                )

            old_status = _value(old, "STAT_CD")
            status = _value(record, "STAT_CD")
            if not (not (old_status == "I" and status != "I" and status != "X")):
                errors.append(
                    {
                        "code": "E5003",
                        "message": "Invoiced order can only be cancelled",
                        "severity": "BLOCK",
                    }
                )

    elif table == "ORD_LINE":
        if event in ("INSERT", "UPDATE"):
            quantity = _number(_value(record, "QTY"))
            if not (quantity > Decimal("0")):
                errors.append(
                    {
                        "code": "E5004",
                        "message": "Quantity must be positive",
                        "severity": "BLOCK",
                    }
                )

        if event == "INSERT":
            active_flag = _lookup(
                tables,
                "PROD_MASTER",
                "PROD_ID",
                _value(record, "PROD_ID"),
                "ACTIVE_FLG",
            )
            if not (active_flag == "Y"):
                errors.append(
                    {
                        "code": "E5005",
                        "message": "Product not active",
                        "severity": "BLOCK",
                    }
                )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
